// Point Wrangle in a SOP that a TOP graph cooks per work item.
// A Wedge TOP exposes its value as a detail attribute 'seed'; use
// it so every work item produces a different variant.
float seed = detail(0, "seed", 0);
@P += vector(rand(set(@ptnum, seed))) * chf("jitter");

// Detail Wrangle in a PDG-cooked SOP. The TOP graph passes the
// work item index in as the detail attribute 'pdg_index'; copy it
// onto a stable attribute for a later merge to sort on.
i@workitem = int(detail(0, "pdg_index", 0));
